package com.unicarona.privacy;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.unicarona.UniCaronaApplication;
import com.unicarona.auth.config.AuthSettings;
import com.unicarona.file.config.StorageSettings;
import com.unicarona.privacy.config.*;
import com.unicarona.privacy.dto.*;
import com.unicarona.privacy.service.*;
import com.unicarona.security.*;
import com.unicarona.support.*;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.boot.*;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

/** Actual PostgreSQL, independent case evidence and archive restore; synthetic identities only. */
class DriverApplicationRetentionIT {
    @TempDir Path temporary;private static RealPostgres database;private ServletWebServerApplicationContext app;private JdbcTemplate sql;private String[] args;
    private static final String PASSWORD="Synthetic driver metadata test password 2026";
    @BeforeAll static void database(){database=new RealPostgres();}
    @AfterAll static void databaseClose(){if(database!=null)database.close();}
    @AfterEach void close(){if(app!=null){app.close();app=null;}}
    @BeforeEach void setup()throws Exception {
        database.resetSchema();var values=new ArrayList<>(List.of(AuthTestSettings.arguments(database.apiConnectionUrl())));values.addAll(List.of("--STORAGE_PATH="+temporary.resolve("files"),"--FRONTEND_PATH="+temporary.resolve("public"),"--PRIVACY_OPERATIONS_ROOT="+temporary.resolve("ops"),"--PRIVACY_ERASURE_JOURNAL_PATH="+temporary.resolve("journal"),"--DEV_MAIL_PATH="+temporary.resolve("mail")));args=values.toArray(String[]::new);
        var env=new MockEnvironment();for(String arg:args){int at=arg.indexOf('=');env.withProperty(arg.substring(2,at),arg.substring(at+1));}var json=new ObjectMapper();var crypto=new CryptoService();var auth=new AuthSettings(env);var files=new StorageSettings(env);new PrivacyBackupCatalog(new PrivacyOperationsSettings(env,files),new PrivacySettings(env),new PrivacySigningKeys(env,auth,crypto,json),json,Clock.systemUTC()).initialize();start();
    }
    private void start(){app=(ServletWebServerApplicationContext)new SpringApplicationBuilder(UniCaronaApplication.class).run(args);sql=app.getBean(JdbcTemplate.class);}
    private Actor owner(){String hash=app.getBean(CryptoService.class).hashPassword(PASSWORD);UUID id=sql.queryForObject("INSERT INTO users(email,password_hash,name,birth_date,email_verified_at) VALUES(?,?,'Synthetic driver metadata owner','2000-01-01',now()) RETURNING id",UUID.class,UUID.randomUUID()+"@example.test",hash);return new Actor(id,"user","active",null,null,null,true,Set.of());}
    private Actor admin(){var value=owner();sql.update("UPDATE users SET role='admin' WHERE id=?",value.id());var tokens=app.getBean(com.unicarona.auth.service.AuthService.class).login(sql.queryForObject("SELECT email FROM users WHERE id=?",String.class,value.id()),PASSWORD).tokens();return new Actor(value.id(),"admin","active",tokens.sessionId(),null,null,true,Set.of("ROLE_ADMIN"));}
    private UUID application(Actor owner,String status,int age){
        UUID vehicle=sql.queryForObject("INSERT INTO vehicles(owner_id,model,color,plate,capacity,status,created_at,updated_at) VALUES(?,'Synthetic metadata vehicle','Black','ABC1D23',4,?,now()-(?*interval '1 day'),now()-(?*interval '1 day')) RETURNING id",UUID.class,owner.id(),"approved".equals(status)?"approved":"rejected",age,age);
        if("approved".equals(status))sql.update("INSERT INTO driver_profiles(user_id,status,approved_at) VALUES(?,'approved',now()-(?*interval '1 day')) ON CONFLICT(user_id) DO NOTHING",owner.id(),age);
        return sql.queryForObject("INSERT INTO driver_applications(user_id,vehicle_id,status,decision,created_at,reviewed_at,documents_expires_at,documents_retired_at) VALUES(?,?,?,'Synthetic private review narrative',now()-((?+1)*interval '1 day'),CASE WHEN ? THEN now()-(?*interval '1 day') ELSE NULL END,now()-interval '1 day',CASE WHEN ? THEN NULL ELSE now() END) RETURNING id",UUID.class,owner.id(),vehicle,status,age,Set.of("approved","rejected").contains(status),age,"pending".equals(status));
    }
    private UUID vehicle(UUID application){return sql.queryForObject("SELECT vehicle_id FROM driver_applications WHERE id=?",UUID.class,application);}
    private PrivacyDriverApplicationRetention tx(){return app.getBean(PrivacyDriverApplicationRetention.class);}
    private boolean retire(Actor owner,UUID application)throws Exception{return tx().retire(new PrivacyDriverApplicationRetention.Candidate("application",application,owner.id()),true);}
    private void guard()throws Exception{app.getBean(PrivacyRestoreGuard.class).run(new DefaultApplicationArguments());}
    private PrivacyHoldDto.Item hold(Actor admin,Actor owner,UUID id){return app.getBean(AdminPrivacyHoldService.class).create(admin,new PrivacyHoldDto.Create(PASSWORD,owner.id(),"driver_application",id,"regular_exercise_of_rights","Synthetic specific review dispute requiring preservation","Synthetic driver case",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(86400)),UUID.randomUUID().toString());}
    private String held(Actor admin,UUID hold){return new String(app.getBean(AdminPrivacyHoldService.class).heldData(admin,hold,new PrivacyDto.Reauthenticate(PASSWORD)).data(),java.nio.charset.StandardCharsets.UTF_8);}
    @Test void ordinaryListsAndExportHideExpiredNarrativesBeforeMaintenance()throws Exception {
        var owner=owner();UUID id=application(owner,"approved",91);var list=app.getBean(com.unicarona.driver.repository.DriverRepository.class).applications(owner.id(),false,10,0,null);assertNull(list.getFirst().decision());assertEquals("approved",list.getFirst().status());assertEquals("Synthetic private review narrative",sql.queryForObject("SELECT decision FROM driver_applications WHERE id=?",String.class,id));var output=new java.io.ByteArrayOutputStream();app.getBean(PrivacyExportService.class).write(owner.id(),output);try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(output.toByteArray()))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry())if(entry.getName().equals("dados.json")){var data=app.getBean(ObjectMapper.class).readTree(zip.readAllBytes());assertTrue(data.path("driverApplications").get(0).path("decision").isNull());}}
    }
    @Test void aRecentNarrativeSurvivesAndAgedReviewIsMinimizedWithoutRevokingApproval()throws Exception {
        var owner=owner();UUID id=application(owner,"approved",89),vehicle=vehicle(id);var admin=admin();sql.update("UPDATE driver_applications SET reviewed_by=? WHERE id=?",admin.id(),id);assertFalse(retire(owner,id));assertNotNull(app.getBean(com.unicarona.driver.repository.DriverRepository.class).applications(owner.id(),false,1,0,null).getFirst().decision());sql.update("UPDATE driver_applications SET reviewed_at=now()-interval '91 days' WHERE id=?",id);Timestamp reviewed=sql.queryForObject("SELECT reviewed_at FROM driver_applications WHERE id=?",Timestamp.class,id);assertTrue(retire(owner,id));assertFalse(retire(owner,id));assertTrue(sql.queryForObject("SELECT decision IS NULL AND reviewed_by IS NULL AND status='approved' AND reviewed_at=? FROM driver_applications WHERE id=?",Boolean.class,reviewed,id));assertEquals("approved",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));assertEquals("approved",sql.queryForObject("SELECT status FROM vehicles WHERE id=?",String.class,vehicle));assertEquals("active",sql.queryForObject("SELECT account_status FROM users WHERE id=?",String.class,owner.id()));
    }
    @Test void closedApplicationsAndUnreferencedVehiclesAreRemovedAfterTheirOwnYear()throws Exception {
        var owner=owner();UUID id=application(owner,"rejected",366),vehicle=vehicle(id);assertTrue(retire(owner,id));assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));assertTrue(tx().retire(new PrivacyDriverApplicationRetention.Candidate("vehicle",vehicle,owner.id()),true));assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM vehicles WHERE id=?)",Boolean.class,vehicle));assertTrue(app.getBean(com.unicarona.driver.repository.DriverRepository.class).applications(owner.id(),false,10,0,null).isEmpty());assertEquals(0,sql.queryForObject("SELECT count(*) FROM audit_logs WHERE action='driver_metadata_minimized' AND (actor_id IS NOT NULL OR resource_id IS NOT NULL OR metadata::text LIKE ?)",Integer.class,"%"+id+"%"));
    }
    @Test void recentClosedRecordsAndPendingPurposeAreNotDeletedByMetadataMaintenance()throws Exception {
        var owner=owner();UUID recent=application(owner,"expired",363),pending=application(owner,"pending",400);retire(owner,recent);retire(owner,pending);assertEquals(2,sql.queryForObject("SELECT count(*) FROM driver_applications WHERE user_id=?",Integer.class,owner.id()));assertEquals("pending",sql.queryForObject("SELECT status FROM driver_applications WHERE id=?",String.class,pending));assertEquals("expired",sql.queryForObject("SELECT status FROM driver_applications WHERE id=?",String.class,recent));
    }
    @Test void currentApprovalAndRecentRetirementKeepMinimumEvidenceThenExpire()throws Exception {
        var owner=owner();UUID id=application(owner,"approved",800),vehicle=vehicle(id);assertTrue(retire(owner,id));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));sql.update("UPDATE vehicles SET status='retired',updated_at=now()-interval '364 days' WHERE id=?",vehicle);assertFalse(retire(owner,id));sql.update("UPDATE vehicles SET updated_at=now()-interval '366 days' WHERE id=?",vehicle);assertTrue(retire(owner,id));
    }
    @Test void caseCreatedAfterOrdinaryExpiryCannotRecoverAnExpiredNarrative()throws Exception {
        var owner=owner();var admin=admin();UUID id=application(owner,"rejected",366);var hold=hold(admin,owner,id);assertFalse(held(admin,hold.id()).contains("Synthetic private review narrative"));assertTrue(held(admin,hold.id()).contains("rejected"));assertTrue(retire(owner,id));assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));assertTrue(held(admin,hold.id()).contains(id.toString()));
    }
    @Test void casePreservesTimelyNarrativePrivatelyAcrossItsDeadlineAndPhysicalArchiveRestore()throws Exception {
        var owner=owner();var admin=admin();UUID id=application(owner,"approved",89);sql.update("UPDATE driver_applications SET reviewed_at=clock_timestamp()-interval '90 days'+interval '3 seconds' WHERE id=?",id);Instant deadline=sql.queryForObject("SELECT reviewed_at+interval '90 days' FROM driver_applications WHERE id=?",Timestamp.class,id).toInstant();Path archive=temporary.resolve("before-driver-metadata-hold.dump");database.dumpDatabaseArchive(archive);var hold=hold(admin,owner,id);assertTrue(held(admin,hold.id()).contains("Synthetic private review narrative"));long wait=Duration.between(Instant.now(),deadline.plusMillis(100)).toMillis();assertTrue(wait<8000);if(wait>0)Thread.sleep(wait);assertTrue(retire(owner,id));assertNull(sql.queryForObject("SELECT decision FROM driver_applications WHERE id=?",String.class,id));app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(archive);start();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertNull(sql.queryForObject("SELECT decision FROM driver_applications WHERE id=?",String.class,id));assertTrue(held(admin,hold.id()).contains("Synthetic private review narrative"));assertEquals("approved",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));
    }
    @Test void postBackupHoldDoesNotRequireRecreatingTheOrdinaryClosedApplication()throws Exception {
        var owner=owner();var admin=admin();UUID id=application(owner,"rejected",366);Path archive=temporary.resolve("before-closed-driver-hold.dump");database.dumpDatabaseArchive(archive);var hold=hold(admin,owner,id);assertTrue(retire(owner,id));app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(archive);start();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));assertTrue(held(admin,hold.id()).contains("rejected"));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM privacy_retained_records WHERE category='driver_application' AND hold_only)",Boolean.class));
    }
    @Test void caseOwnershipAndUnavailableResourcesAreCheckedAndReleaseEndsPrivateAccess()throws Exception {
        var owner=owner();var other=owner();var admin=admin();UUID id=application(owner,"rejected",89);assertEquals("PRIVACY_RESOURCE_UNAVAILABLE",assertThrows(com.unicarona.shared.ApiException.class,()->hold(admin,other,id)).code());var hold=hold(admin,owner,id);app.getBean(AdminPrivacyHoldService.class).review(admin,hold.id(),new PrivacyHoldDto.Review(PASSWORD,1,"release","Synthetic case concluded without further retention","Synthetic driver case",null,null),UUID.randomUUID().toString());assertEquals("PRIVACY_HOLD_INACTIVE",assertThrows(com.unicarona.shared.ApiException.class,()->held(admin,hold.id())).code());app.getBean(PrivacyRetentionTransactions.class).prune(100);assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_retained_records WHERE category='driver_application'",Integer.class));sql.update("DELETE FROM driver_applications WHERE id=?",id);assertEquals("PRIVACY_RESOURCE_UNAVAILABLE",assertThrows(com.unicarona.shared.ApiException.class,()->hold(admin,owner,id)).code());
    }
    @Test void aLockedOwnerDoesNotStarveAnotherExpiredApplication()throws Exception {
        for(var owner:List.of(owner(),owner()))application(owner,"rejected",366);var first=tx().candidates(null,null,1).getFirst();var locked=new CountDownLatch(1);var release=new CountDownLatch(1);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var writer=executor.submit(()->app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{sql.queryForList("SELECT id FROM users WHERE id=? FOR UPDATE",first.owner());locked.countDown();try{assertTrue(release.await(15,TimeUnit.SECONDS));}catch(InterruptedException stop){Thread.currentThread().interrupt();throw new IllegalStateException(stop);}}));try{assertTrue(locked.await(8,TimeUnit.SECONDS));var task=app.getBean(PrivacyDriverApplicationMaintenance.class);assertEquals(0,task.runOnce(1,()->false));assertEquals(1,task.runOnce(1,()->false));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,first.id()));}finally{release.countDown();}writer.get(8,TimeUnit.SECONDS);}finally{release.countDown();}
    }
    @Test void anUnconfirmedIndependentCheckpointStopsMetadataDeletion()throws Exception {
        var owner=owner();UUID id=application(owner,"rejected",366);app.getBean(PrivacyHoldControlJournal.class).prepare(app.getBean(ObjectMapper.class).createObjectNode().put("syntheticUnconfirmedPreparation",true));assertThrows(java.io.IOException.class,()->retire(owner,id));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));assertFalse(app.getBean(PrivacyReadiness.class).ready());
    }
    @Test void approvalLinkedToTransportKeepsOnlyItsMinimumEvidence()throws Exception {
        var owner=owner();UUID id=application(owner,"approved",800),vehicle=vehicle(id);sql.update("UPDATE vehicles SET status='retired' WHERE id=?",vehicle);UUID university=sql.queryForObject("INSERT INTO universities(slug,name,city,state_code) VALUES(?,'Synthetic campus','Synthetic city','GO') RETURNING id",UUID.class,"metadata-"+UUID.randomUUID());UUID route=sql.queryForObject("INSERT INTO ride_routes(university_id,driver_id,region,meeting,distance_m) VALUES(?,?,'Synthetic region','Synthetic meeting',12000) RETURNING id",UUID.class,university,owner.id());UUID price=sql.queryForObject("INSERT INTO pricing_versions(university_id,fuel_cents,efficiency,wear_cents,reference_passengers,commission_bps,discount_bps) VALUES(?,600,10,10,3,1000,0) RETURNING id",UUID.class,university);sql.update("INSERT INTO rides(university_id,route_id,driver_id,vehicle_id,direction,ride_date,departure_time,capacity,price_cents,commission_bps,pricing_version_id,status) VALUES(?,?,?,?,'ida',current_date-700,'08:00',4,1000,1000,?,'completed')",university,route,owner.id(),vehicle,price);assertTrue(retire(owner,id));assertFalse(retire(owner,id));assertTrue(sql.queryForObject("SELECT decision IS NULL AND status='approved' FROM driver_applications WHERE id=?",Boolean.class,id));assertFalse(tx().retire(new PrivacyDriverApplicationRetention.Candidate("vehicle",vehicle,owner.id()),true));assertEquals(1,sql.queryForObject("SELECT count(*) FROM rides WHERE vehicle_id=?",Integer.class,vehicle));
    }
    @Test void aCaseWithoutItsPrivateCopyDoesNotAuthorizeDestructiveMetadataCleanup()throws Exception {
        var owner=owner();var admin=admin();UUID id=application(owner,"rejected",366);hold(admin,owner,id);sql.update("DELETE FROM privacy_retained_records WHERE user_id=? AND category='driver_application'",owner.id());assertFalse(retire(owner,id));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));assertTrue(tx().candidates(null,null,100).stream().noneMatch(c->c.id().equals(id)));
    }
    @Test void ownerExportIncludesPrivateCaseCopyWithOnlyApplicantFields()throws Exception {
        var owner=owner();var admin=admin();UUID id=application(owner,"rejected",20);sql.update("UPDATE driver_applications SET reviewed_by=? WHERE id=?",admin.id(),id);hold(admin,owner,id);var output=new java.io.ByteArrayOutputStream();app.getBean(PrivacyExportService.class).write(owner.id(),output);boolean found=false;try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(output.toByteArray()))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry())if(entry.getName().equals("dados.json")){var data=app.getBean(ObjectMapper.class).readTree(zip.readAllBytes());var copy=data.path("retainedDriverApplications").get(0).path("content");assertEquals("Synthetic private review narrative",copy.path("decision").asText());assertFalse(copy.has("reviewed_by"));assertTrue(copy.path("reviewed_at").isTextual());assertEquals(id.toString(),copy.path("id").asText());found=true;}}assertTrue(found);
    }
    @Test void technicalVehicleReplayCannotRenewTheOriginalAccountErasurePurposeBoundary()throws Exception {
        var owner=owner();UUID id=application(owner,"approved",800),vehicle=vehicle(id);sql.update("UPDATE users SET deleted_at=now(),account_status='deleted' WHERE id=?",owner.id());sql.update("UPDATE vehicles SET status='retired',deleted_at=now(),updated_at=now() WHERE id=?",vehicle);UUID closure=sql.queryForObject("INSERT INTO privacy_account_closures(user_id,initiated_by,status,previous_account_status,requested_at,reauthenticated_at,erase_after,completed_at,policy_version) VALUES(?,'user','completed','active',now()-interval '368 days',now()-interval '368 days',now()-interval '367 days',now()-interval '366 days','synthetic-stable-deadline') RETURNING id",UUID.class,owner.id());sql.update("INSERT INTO privacy_erasure_tasks(closure_id,user_id,status,prepared_at,suppression_until,journaled_at,scrubbed_at,completed_at) VALUES(?,?,'completed',now()-interval '366 days',now()-interval '330 days',now()-interval '366 days',now()-interval '366 days',now()-interval '366 days')",closure,owner.id());assertTrue(retire(owner,id));assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM driver_applications WHERE id=?)",Boolean.class,id));assertTrue(tx().retire(new PrivacyDriverApplicationRetention.Candidate("vehicle",vehicle,owner.id()),true));assertEquals(1,sql.queryForObject("SELECT count(*) FROM privacy_erasure_tasks WHERE closure_id=?",Integer.class,closure));
    }
}
